function state(active){const p=json('CURRENT_CHECKPOINT.json');assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='cervical-vascular-qa');if(active)p.activeWork.current.activeExecutionSessions.push({role:'cervical-vascular-qa',pid:process.pid,evidence:dir,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);}const write=(name,v)=>fs.writeFileSync(dir+'/'+name,JSON.stringify(v,null,2)+'\n',{flag:'wx'});
let closing=false;function close(reason){if(closing)return;closing=true;server.close(()=>{write('REQUESTS.json',requests);write('TERMINAL.json',{at:new Date().toISOString(),code:0,pid:process.pid,reason,graceful:true,previewChanged:false});state(false);process.exit(0);});}
server.listen(0,'127.0.0.1',()=>{const base='http://127.0.0.1:'+server.address().port;write('STARTED.json',{at:new Date().toISOString(),base,pid:process.pid,sourceCommit:manifest.sourceCommit,manifestSha256:hash(root+'/manifest.json'),actualExportedModule:true,applicationBytesUnmodified:true,authDataOrPrivateAssetsServed:false,previewChanged:false});state(true);console.log(JSON.stringify({base,pid:process.pid,quit:'q'}));});process.stdin.setEncoding('utf8');process.stdin.on('data',s=>{if(s.trim()==='q')close('q');});process.stdin.on('end',()=>close('stdin-ended'));process.on('SIGINT',()=>close('SIGINT'));process.on('SIGTERM',()=>close('SIGTERM'));
